--   12 periods · 144 lines · 17 without a receipt link
--   49 lines whose date the sheet did not record (dated to their period's last day)
--   Every period settled except Aug 2026, which is left OPEN owing 9,726.26.
--
-- THE CUSTODIAN is resolved by lookup, never hard-coded to an id this file cannot know.
-- If nobody matches, the import does nothing and says so — a half-imported ledger is worse
-- than an empty one.
--
-- IDEMPOTENT: every row carries a deterministic id and every insert is ON CONFLICT DO NOTHING.

BEGIN;

DO $import$
DECLARE
  v_custodian TEXT;
  v_finance   TEXT;
  v_account   TEXT := 'pca_marketing';
BEGIN
  -- Raneem Sarhaan, Marketing Manager — the workbook's "SUBMITTED BY" on every tab.
  SELECT id INTO v_custodian FROM "User"
   WHERE lower(email) = 'raneem.sarhaan@forefront.consulting' AND status = 'ACTIVE' LIMIT 1;
  IF v_custodian IS NULL THEN
    SELECT id INTO v_custodian FROM "User"
     WHERE name ILIKE '%raneem%' AND status = 'ACTIVE' ORDER BY "createdAt" LIMIT 1;
  END IF;
  IF v_custodian IS NULL THEN
    RAISE WARNING 'marcom import skipped: no active user matching Raneem Sarhaan';
    RETURN;
  END IF;

  -- Mohamed Selim, Finance — the workbook's "SUBMITTED TO". Optional: every column that
  -- records him is nullable, so a missing match costs an attribution, not the import.
  SELECT id INTO v_finance FROM "User"
   WHERE name ILIKE '%selim%' AND status = 'ACTIVE' ORDER BY "createdAt" LIMIT 1;

  INSERT INTO "PettyCashAccount" ("id","name","status","custodianId","createdById","createdAt","updatedAt")
  VALUES (v_account, 'Marketing petty cash', 'ACTIVE', v_custodian, v_finance, now(), now())
  ON CONFLICT ("id") DO NOTHING;

